def _checked(ranges):
    """Validate every range and return fresh (start, end) tuples. Does not mutate input."""
    out = []
    for r in ranges:
        start, end = r
        if not (isinstance(start, int) and isinstance(end, int)):
            raise TypeError("range bounds must be int")
        if start > end:
            raise ValueError(f"invalid range {(start, end)}: start > end")
        out.append((start, end))
    return out


def merge(ranges):
    """Join overlapping and neighbouring closed integer ranges. See TASK.md."""
    items = sorted(_checked(ranges))
    result = []
    for start, end in items:
        if result and start <= result[-1][1] + 1:
            last_start, last_end = result[-1]
            if end > last_end:
                result[-1] = (last_start, end)
        else:
            result.append((start, end))
    return result


def subtract(ranges, holes):
    """The integers in `ranges` that are not in `holes`, as merged ranges."""
    base = merge(ranges)
    cut = merge(holes)
    result = []
    j = 0
    for start, end in base:
        # skip holes entirely before this range
        while j < len(cut) and cut[j][1] < start:
            j += 1
        k = j
        cur = start
        while k < len(cut) and cut[k][0] <= end:
            h_start, h_end = cut[k]
            if h_start > cur:
                result.append((cur, h_start - 1))
            cur = max(cur, h_end + 1)
            if h_end > end:
                break
            k += 1
        if cur <= end:
            result.append((cur, end))
    return result


def count(ranges):
    """How many distinct integers the ranges hold."""
    return sum(end - start + 1 for start, end in merge(ranges))
